   102	        pd.set(3, 0);                   // transB
   103	        pd.set(4, 1);                   // constantA
   104	        pd.set(5, 0);                   // constantB
   105	        pd.set(6, 1);                   // constantC
   106	        pd.set(7, num_output);          // M = outch
   107	        pd.set(8, 0);                   // N = size
   108	        pd.set(9, maxk * num_input);    // K = maxk*inch
   109	        pd.set(10, bias_term ? 1 : -1); // constant_broadcast_type_C = (M)
   110	        pd.set(11, 1);                  // output_N1M
   111	
   112	        gemm->load_param(pd);
   113	
   114	        // maxk-inch-outch to pa-maxk-inch/pa-outch
   115	        Mat tmp;
   116	        {
