   118	
   119	            tmp.create(maxk * num_input, num_output);
   120	
   121	            for (int q = 0; q < num_output; q += 1)
   122	            {
   123	                float* g00 = tmp.row(q);
   124	
   125	                for (int p = 0; p + (elempack - 1) < num_input; p += elempack)
   126	                {
   127	                    for (int k = 0; k < maxk; k++)
   128	                    {
   129	                        for (int i = 0; i < elempack; i++)
   130	                        {
   131	                            const float* k00 = weight_data_r2.channel(q).row(p + i);
