   192	static inline float bilinear_sample_scalar(const Mat& img, int h, int w, float h_im, float w_im)
   193	{
   194	    const bool cond = h_im > -1 && w_im > -1 && h_im < h && w_im < w;
   195	    if (!cond) return 0.f;
   196	
   197	    int h_low = (int)floorf(h_im);
   198	    int w_low = (int)floorf(w_im);
   199	    int h_high = h_low + 1;
   200	    int w_high = w_low + 1;
   201	
   202	    float lh = h_im - h_low;
   203	    float lw = w_im - w_low;
   204	    float hh = 1 - lh;
   205	    float hw = 1 - lw;
   206	
   207	    bool v1_cond = (h_low >= 0 && w_low >= 0);
   208	    bool v2_cond = (h_low >= 0 && w_high <= w - 1);
   209	    bool v3_cond = (h_high <= h - 1 && w_low >= 0);
   210	    bool v4_cond = (h_high <= h - 1 && w_high <= w - 1);
   211	
   212	    float w1 = hh * hw;
   213	    float w2 = hh * lw;
   214	    float w3 = lh * hw;
   215	    float w4 = lh * lw;
   216	
   217	    float v1 = v1_cond ? img.row(h_low)[w_low] : 0.f;
   218	    float v2 = v2_cond ? img.row(h_low)[w_high] : 0.f;
   219	    float v3 = v3_cond ? img.row(h_high)[w_low] : 0.f;
   220	    float v4 = v4_cond ? img.row(h_high)[w_high] : 0.f;
   221	
   222	    return w1 * v1 + w2 * v2 + w3 * v3 + w4 * v4;
   223	}
